-- case_info
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (1,'乳源华景雅苑 — 阳台全景封窗','','','18 楼高层阳台，采用断桥铝 90 系列重型推拉窗 + 大板中空玻璃封窗方案。加装防风扣件，抗 12 级台风。业主评价：视野开阔、隔音效果好，刮风天再也不用担心。','碧桂园18栋A702','断桥铝平开窗','108系列','5+20A','德国好博','','','更换前为普通铝合金单层玻璃推拉窗，密封性差，隔音隔热效果不理想，冬季室内温度流失严重。','更换为70系列断桥铝内开内倒窗，双层中空钢化玻璃，隔音提升显著，室内温度稳定。','家有小孩，需要考虑防护','装完感觉整个家都亮堂了','2天',0,1,'2026-05-10 17:39:42','105,118,101',0);
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (2,'乳城镇张先生自建房 — 全屋门窗方案','','','3 层自建房，入口甲级不锈钢防盗门，室内实木复合烤漆门，窗户全部采用 70 系列断桥铝外开窗。针对山区风压定制加厚型材 + 强化连接件。','','','','','','','','','','','','',0,1,'2026-05-10 17:39:42','100',0);
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (3,'县城解放路临街商铺 — 不锈钢卷帘门','',NULL,'临街手机店更换电动不锈钢卷帘门，门宽 5 米。旧门拆除 + 新门安装 1 天完成。配遥控 + 手动双模式，停电无忧。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-05-10 17:39:42','108',0);
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (4,'老城区陈姨旧窗改造','',NULL,'30 年老房子，原铁窗锈蚀严重、墙体开裂。拆旧后修补窗洞 + 防水密封，换装断桥铝平开窗。改造后不渗水、隔音好、冬天室内升温 3°C。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-05-10 17:39:42','116',0);
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (5,'乳源碧水蓝湾 — 断桥铝推拉门','',NULL,'客厅与阳台之间安装 100 系列断桥铝提升推拉门。门扇 2.5m 宽，推拉轻便、关闭紧密。高轨防水设计应对暴雨天，业主说比普通推拉门强太多。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-05-10 17:39:42','104',0);
MERGE INTO case_info (`id`, `title`, `image`, `images`, `description`, `location`, `product_type`, `profile_spec`, `glass_config`, `hardware_brand`, `before_image`, `before_images`, `before_desc`, `after_desc`, `customer_need`, `customer_review`, `install_duration`, `sort`, `is_show`, `create_time`, `product_id`, `deleted`) KEY(id) VALUES (6,'桂头镇李宅 — 新中式实木门','',NULL,'乡村住宅 5 扇室内门全部定制新中式实木工艺门。浅胡桃色水性漆，雕刻回纹图案。尺寸根据门洞实测定制，安装严丝合缝。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2026-05-10 17:39:42','111',0);

