MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (112,12,'三元乙丙密封胶条（耐候型）','JT-EPDM','三元乙丙橡胶（EPDM）',15.00,'','三元乙丙汽车级密封胶条，耐候抗老化性能为普通橡胶3倍。专为粤北山区高湿气候优化，-40℃~120℃不变形不脆化，使用寿命10年以上。按米计价。',',','{\"型材:材质\":\"EPDM 三元乙丙橡胶\",\"型材:耐温范围\":\"-40℃~120℃\",\"型材:适用槽口\":\"欧标/国标\",\"五金:品牌\":\"硅宝\",\"花色:可选颜色\":\"黑色, 灰色\",\"工艺:寿命\":\"10年以上\",\"工艺:特点\":\"耐臭氧/耐UV/弹性好\",\"服务:质保\":\"3年\",\"服务:计价\":\"按米\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (113,13,'304不锈钢轴承铰链（防锈型）','HJ-304','304不锈钢 + 进口密封轴承',48.00,'','304不锈钢轴承铰链，进口密封轴承，盐雾测试500小时不锈。专为高湿山区环境设计，单只承重80kg，三维可调，开合顺畅无异响。',',','{\"型材:材质\":\"304不锈钢\",\"型材:轴承\":\"进口密封轴承\",\"型材:厚度\":\"3.0mm\",\"五金:承重\":\"80kg/只\",\"五金:调节\":\"三维可调（上下/左右/前后）\",\"五金:盐雾测试\":\"500小时\",\"花色:颜色\":\"不锈钢原色\",\"工艺:表面\":\"拉丝处理\",\"服务:质保\":\"5年\",\"服务:计价\":\"按只\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (114,14,'双层中空钢化玻璃（5+20A+5）','BL-ZK05','浮法玻璃 + 钢化处理 + 铝间隔条',128.00,'','5+20A+5双层中空钢化玻璃，CCC认证激光刻印。铝条内填分子筛干燥剂，长效不起雾。可按需定制Low-E镀膜、磨砂、夹胶等附加工艺。',',','{\"型材:规格\":\"5+20A+5mm\",\"型材:原片品牌\":\"信义/南玻\",\"型材:认证\":\"CCC钢化\",\"玻璃:可选配置\":\"Low-E镀膜, 磨砂/玉砂, 夹胶PVB\",\"玻璃:中空处理\":\"铝间隔条 + 分子筛干燥剂\",\"玻璃:可选规格\":\"5+24A+5, 6+20A+6\",\"工艺:折弯\":\"一体折弯（防漏气）\",\"花色:可选颜色\":\"透明, 超白, 灰玻, 茶玻\",\"服务:质保\":\"3年\",\"服务:计价\":\"按㎡\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (115,15,'304不锈钢防护栏杆','LG-304','304不锈钢',298.00,'A001.jpg','304不锈钢阳台防护栏杆，竖杆间距≤11cm符合国标安全规范，法兰焊接安装稳固不晃动。适用于阳台、楼梯、走廊等。按米计价。','A001.jpg,A001-1.jpg','{\"型材:材质\":\"304不锈钢\",\"型材:主管\":\"Φ50×1.5mm\",\"型材:竖杆\":\"Φ19×1.0mm\",\"型材:竖杆间距\":\"≤11cm（国标安全）\",\"五金:安装\":\"法兰膨胀螺栓\",\"花色:颜色\":\"不锈钢原色, 黑色, 白色\",\"工艺:表面\":\"拉丝防锈\",\"工艺:焊接\":\"氩弧焊满焊\",\"服务:质保\":\"5年\",\"服务:计价\":\"按米（含安装）\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (116,16,'老旧门窗拆换一体化服务','FW-CH01','全包（拆旧 → 修补 → 防水 → 安装）',0.00,'','针对乳源老城区20年以上房龄房屋，提供老旧门窗拆换一体化服务。包含：①旧门窗拆除 ②墙体缺口专业修补 ③聚氨酯防水密封 ④新门窗安装调试。拒绝野蛮拆除导致的渗水开裂。免费上门评估，价格面议。',',','{\"型材:适用对象\":\"20年以上老城区房屋\",\"型材:改造范围\":\"窗户/门/阳台封窗\",\"服务:①拆除\":\"专业工具无损拆旧\",\"服务:②修补\":\"墙体缺口砂浆修补\",\"服务:③防水\":\"聚氨酯防水打底\",\"服务:④安装\":\"新门窗标准安装调试\",\"服务:工期\":\"1-3天（视数量）\",\"服务:质保\":\"整体2年\",\"服务:计价\":\"面议（免费上门评估出方案）\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (117,17,'乡村自建房门窗整体方案','FW-ZJ01','定制（测量 → 设计 → 生产 → 安装）',0.00,'','为乳源各镇乡村自建房量身定制门窗整体方案。综合考虑山区风压、房屋朝向、采光通风等因素，强化连接件稳固性。提供断桥铝/不锈钢/木门组合方案，一站式配齐。免费上门测量出图。',',','{\"型材:适用对象\":\"乡村自建房（2-4层）\",\"型材:设计要素\":\"风压/朝向/采光/通风\",\"服务:①测量\":\"免费上门精准测量\",\"服务:②设计\":\"CAD方案图 + 3D效果可选\",\"服务:③产品\":\"断桥铝/不锈钢/木门组合\",\"服务:④安装\":\"自有安装团队施工\",\"服务:工期\":\"7-15天（视面积）\",\"服务:质保\":\"型材10年/五金5年/玻璃3年\",\"服务:计价\":\"面议（免费上门测量出方案）\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);
MERGE INTO product (`id`, `category_id`, `name`, `model`, `material`, `price`, `cover_image`, `description`, `images`, `specs`, `price_tag`, `price_breakdown`, `pricing_rule`, `reference_price`, `option_prices`, `performance`, `is_show`, `create_time`, `deleted`) KEY(id) VALUES (118,18,'门窗维修养护耗材包','HC-B01','密封胶 + 轨道润滑剂 + 五金清洁防锈喷雾',68.00,'','专为粤北山区高湿气候搭配的门窗日常养护三件套：①专用耐候密封胶 ②轨道滑轮润滑剂 ③五金清洁防锈喷雾。简单操作即可延长门窗使用寿命3-5年。',',','{\"型材:套装内容\":\"密封胶×1 + 润滑剂×1 + 防锈喷雾×1\",\"型材:密封胶\":\"硅宝耐候密封胶 300ml\",\"型材:润滑剂\":\"轨道专用润滑脂 50ml\",\"型材:防锈喷雾\":\"五金防锈清洁剂 200ml\",\"服务:适用\":\"断桥铝/铝合金/不锈钢门窗\",\"服务:效果\":\"延长寿命3-5年\",\"服务:使用频率\":\"建议每6个月养护1次\",\"服务:质保\":\"耗材类无质保\",\"服务:计价\":\"按套\"}','含安装五金',NULL,NULL,NULL,NULL,NULL,1,'2026-05-10 20:03:58',0);

